save(354,dict(paragraphs=["Sudhakar Gaidhani is a Marathi poet associated with Nagpur, whose work includes the epic Devdoot: The Angel. Its circulation in English and Romanian reflects a sustained life in translation: the Romanian National Library records Liviu Pendefunda’s Romanian version, while translator Datta G. Sawant documents his English translations of the fourth and fifth cantos. In an interview with Yang Yujun, Gaidhani describes his poetic style as philosophical and mystical.","‘AGE CAN BE WASHED LIKE A GARMENT’ gives ageing the familiar gestures of washing, mending and caring for cloth. The worn garment requires tenderness rather than force; the mind becomes both a means of cleansing and a current to which life can be entrusted. Its movement toward evening turns an everyday task into a meditation on release."],sources=[source('Polis Magazino — interview with Sudhakar Gaidhani','https://www.polismagazino.gr/interview-with-sudhakar-gaidhani-by-yang-yujun/','Opened author interview: Marathi poetry, Nagpur, Devdoot and self-description philosophical/mystical.'),source('Toshniwal College — Datta G. Sawant publication record','https://www.toshniwalcollege.ac.in/uploaddata/Profile/Arts/English/SawantDG.pdf','Opened CV lists CantoIV andV Marathi-to-English translations,2024, Kusumaee ISBN9788196563523.'),source('Romanian National Library — September2023 catalogue','https://bibnat.ro/wp-content/uploads/2024/03/CIP_septembrie-2023_site.pdf','Opened catalogue indexed page373 entry1908: Devdoot îngerul, authorGaidhani, translatorLiviuPendefunda, ContactInternational2023 ISBN9789739412681.'),source('Nathe Publication — Devdoot ebook listing',u,'Opened publisher-supplied GoogleBooks listing: author and July2022 Nathe edition.')],books=[dict(title='Devdoot: The Angel',detail='Epic poetry. Nathe Publication, 2022 ebook edition.',url=u)],identity_match='Name, Marathi/Nagpur biography match capture; exact poem448 also appears under same byline in Raven Cage93, indexed page236.',poems_read=[dict(id=448,title='AGE CAN BE WASHED LIKE A GARMENT',coverage='Full English source as captured.',basis='Garment, washing/repair, childlike tenderness, mind waves, evening, final release.')],limitations=['No current total of languages, books or awards asserted; supplied figures preserved but not independently counted.','No translator assigned to poem448 because this source does not credit one; existing metadata untouched.','Epic editions differ in extent and translators; 2022 ebook distinguished from 2024 five-canto edition.','No personal religion or medical history inferred from the poem.'],research_leads=[dict(url='https://www.lechasseurabstrait.com/revue/IMG/pdf/ravencagezine93.pdf',finding='Search index reproduces exact poem at page236 with Gaidhani copyright2024; external text not substituted for local source.'),dict(url='https://www.researchgate.net/publication/382331152_Devdoot_the_Angel_Canto_IV_V_translated_from_Marathi_into_English',finding='Translator-uploaded bibliographic/title-page evidence names OmBiyani,VishwasVaidya,DattaSawant for 2024 complete English edition; not conflated with ebook.')],next_action='Independent author/editor review, particularly edition-specific translator credits.'))
